import{_ as e,o as a,c as r,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"Keynote- Building Together- Open Storage for Today and Tomorrow - Joachim Kraftmayer, CEO, CLYSO","description":"","frontmatter":{"title":"Keynote- Building Together- Open Storage for Today and Tomorrow - Joachim Kraftmayer, CEO, CLYSO","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph社区","分布式存储","Ceph技术创新","Ceph产品发布","Open Source"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Keynote_-_Building_Together_-_Open_Storage_for_Today_and_Tomorrow_-_Joachim_Kraftmayer_CEO_CLYSO.md","filePath":"posts/2025/Keynote_-_Building_Together_-_Open_Storage_for_Today_and_Tomorrow_-_Joachim_Kraftmayer_CEO_CLYSO.md","lastUpdated":1780459816000}'),_={name:"posts/2025/Keynote_-_Building_Together_-_Open_Storage_for_Today_and_Tomorrow_-_Joachim_Kraftmayer_CEO_CLYSO.md"};function n(l,o,h,i,p,s){return a(),r("div",null,[...o[0]||(o[0]=[t('<p>Ceph 社区会议纪要</p><p><strong>会议主题：</strong> Ceph 社区发展与技术创新<br><strong>会议时间：</strong> 近期<br><strong>主讲人：</strong> Clyo 公司CEO Joachim Kraftmayer</p><h4 id="_1-开场致辞与感谢" tabindex="-1"><strong>1. 开场致辞与感谢</strong> <a class="header-anchor" href="#_1-开场致辞与感谢" aria-label="Permalink to &quot;**1. 开场致辞与感谢**&quot;">​</a></h4><p>Kraftmayer 先生代表 Clyo 公司对 Safalon 会议的组织者、赞助商及与会者表示感谢，并强调 Ceph 社区的独特性和重要性。他提到自己在 Ceph 社区已有超过十年的参与经验，体现了对社区发展的长期承诺。</p><h4 id="_2-ceph-社区的核心价值观" tabindex="-1"><strong>2. Ceph 社区的核心价值观</strong> <a class="header-anchor" href="#_2-ceph-社区的核心价值观" aria-label="Permalink to &quot;**2. Ceph 社区的核心价值观**&quot;">​</a></h4><p>Kraftmayer 先生强调了 Ceph 社区的核心价值观，包括协作与开源精神，以及技术创新。他提到，最佳技术源于工程师、研究人员和运维人员的开放协作，开源技术是公司的核心理念。</p><h4 id="_3-clyo-对-ceph-社区的贡献" tabindex="-1"><strong>3. Clyo 对 Ceph 社区的贡献</strong> <a class="header-anchor" href="#_3-clyo-对-ceph-社区的贡献" aria-label="Permalink to &quot;**3. Clyo 对 Ceph 社区的贡献**&quot;">​</a></h4><p>Clyo 公司本月已将财务支持提升至对 Ceph Foundation 的最高级别，用于支持上游基础设施、文档、社区管理及活动。Clyo 还将继续举办 Ceph Days 和 Safalon 活动，并预告了即将在柏林举办的下一场 Ceph Days。</p><h4 id="_4-clyo-的技术重点与产品更新" tabindex="-1"><strong>4. Clyo 的技术重点与产品更新</strong> <a class="header-anchor" href="#_4-clyo-的技术重点与产品更新" aria-label="Permalink to &quot;**4. Clyo 的技术重点与产品更新**&quot;">​</a></h4><p>Clyo 的技术重点在于性能调优、集群扩展性、数据持久性和调试工具开发。Clyo 提供紧急技术支持，帮助用户解决 Ceph 相关问题。公司还发布了 Ceph Cluster Analyzer 和 Ceph Config Browser 等工具。</p><ul><li><strong>重磅发布</strong>：Auto（开源 Ceph 助手），帮助运维人员构建和管理高性能存储，提供实时工具和洞察，完全开源，并邀请社区共同测试和改进。</li></ul><h4 id="_5-邀请与展望" tabindex="-1"><strong>5. 邀请与展望</strong> <a class="header-anchor" href="#_5-邀请与展望" aria-label="Permalink to &quot;**5. 邀请与展望**&quot;">​</a></h4><p>Kraftmayer 先生邀请与会者访问 Clyo 展台，讨论 Ceph 的成功案例、挑战及未来愿景。他强调 Ceph 是最佳分布式存储，但更重要的是社区的共同努力。</p><h4 id="_6-行动计划" tabindex="-1"><strong>6. 行动计划</strong> <a class="header-anchor" href="#_6-行动计划" aria-label="Permalink to &quot;**6. 行动计划**&quot;">​</a></h4><ol><li>参与Ceph Days，12月柏林活动报名。</li><li>试用 Auto 工具，社区成员可测试并提供反馈。</li><li>协作开发，鼓励开发者加入 Auto 项目的改进。</li></ol><p><strong>会议结束：</strong> 掌声致谢。</p>',16)])])}const g=e(_,[["render",n]]);export{C as __pageData,g as default};
